import numpy as np
lines=open('initial_complex.xyz').read().splitlines()[2:]
atoms=[(l.split()[0],np.array(list(map(float,l.split()[1:4])))) for l in lines]
N=len(atoms); phos_start=13; phos_len=88; extra_start=phos_start+phos_len
frags={'Ir':[0],'Cp_ring':list(range(1,6)),'Cp_me':list(range(6,11)),'Ir_me':[11,12],'phos':list(range(phos_start,extra_start)),'extraH':list(range(extra_start,N))}
def frag(i):
    for n,idx in frags.items():
        if i in idx: return n
# map extraH to parent heavy: first 15 -> Cp_me indices 6..10 each 3; next 6 -> Ir_me 11,12 each 3
parent={}
k=0
for heavy in list(range(6,11))+[11,12]:
    for _ in range(3):
        parent[extra_start+k]=heavy; k+=1
pairs=[]
for i in range(N):
    for j in range(i+1,N):
        fi,fj=frag(i),frag(j)
        if fi==fj: continue
        # skip extraH-parent bonds
        if parent.get(i)==j or parent.get(j)==i: continue
        # skip other extraH vs Cp/Ir_me? If not parent, count as clash
        d=np.linalg.norm(atoms[i][1]-atoms[j][1])
        pairs.append((d,i,atoms[i][0],fi,j,atoms[j][0],fj))
pairs.sort()
print('closest pairs including H (nonbonded across fragments):')
for p in pairs[:40]: print(tuple(round(float(x),3) if isinstance(x,(float,np.floating)) else x for x in p))
